values
('00000000-0000-4000-8000-000000000001', 'portrait-studio-light', 'Studio light study', 'A quiet portrait setup with soft falloff and a calm, direct gaze.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Photographer-studio-1893.jpg/960px-Photographer-studio-1893.jpg', 'https://commons.wikimedia.org/wiki/File:Photographer-studio-1893.jpg', 'A.H. Wheeler, photographer', 'Public domain', 'Portrait', 'curated', '35 mm film', 'Large-format studio camera', 'Portrait lens', '100', '1/60 s', 'f/5.6', 'Daylight', null, '{"Body position":"Turn slightly toward the key light","Hands":"Rest loosely at waist height","Gaze":"Look just past the lens"}'::jsonb, '{"Contrast":"+8","Highlights":"-12","Grain":"Fine","Preset":"Silver print"}'::jsonb),
('00000000-0000-4000-8000-000000000002', 'portrait-window-light', 'Window light portrait', 'A single-side key keeps the face dimensional while the background stays quiet.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Alice_C._Evans%2C_National_Photo_Company_portrait%2C_circa_1915.jpg/960px-Alice_C._Evans%2C_National_Photo_Company_portrait%2C_circa_1915.jpg', 'https://commons.wikimedia.org/wiki/File:Alice_C._Evans,_National_Photo_Company_portrait,_circa_1915.jpg', 'National Photo Company Collection', 'Public domain', 'Portrait', 'curated', 'Large-format film', 'Portrait camera', '105 mm', '100', '1/125 s', 'f/4', 'Daylight', null, '{"Head":"Chin slightly down","Gaze":"Look toward the brighter side"}'::jsonb, '{"Contrast":"+5","Shadows":"+10","Temperature":"-3","Preset":"Soft Silver"}'::jsonb),
('00000000-0000-4000-8000-000000000003', 'portrait-seated', 'Seated profile', 'Turn the shoulders away, then bring the face back toward the camera.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/James_Abram_Garfield%2C_photo_portrait_seated.jpg/960px-James_Abram_Garfield%2C_photo_portrait_seated.jpg', 'https://commons.wikimedia.org/wiki/File:James_Abram_Garfield,_photo_portrait_seated.jpg', 'Brady-Handy Photograph Collection', 'Public domain', 'Portrait', 'curated', 'Large-format film', 'Portrait camera', '90 mm', '100', '1/60 s', 'f/5.6', 'Daylight', null, '{"Body position":"Sit at a slight angle","Hands":"Rest one hand on the chair","Gaze":"Meet the camera"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000004', 'street-braga', 'A pause in Braga', 'Use repeating windows and a small human figure to give the street depth.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/2026-09-28_Street_scene_in_Braga.jpg/960px-2026-09-28_Street_scene_in_Braga.jpg', 'https://commons.wikimedia.org/wiki/File:2026-09-28_Street_scene_in_Braga.jpg', 'Alexkom000', 'CC BY 4.0', 'Street', 'curated', 'Mirrorless camera', '35 mm prime', '35 mm', '400', '1/500 s', 'f/4', 'Auto', '-0.3 EV', '{"Body position":"Walk through the frame naturally","Gaze":"Look toward the street ahead"}'::jsonb, '{"Highlights":"-18","Shadows":"+8","Saturation":"-4","Preset":"City Neutral"}'::jsonb),
('00000000-0000-4000-8000-000000000005', 'street-seoul', 'Seoul, 1904', 'Layer foreground movement against a still architectural backdrop.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/A_Street_Scene_in_Seoul%2C_1904.jpg/960px-A_Street_Scene_in_Seoul%2C_1904.jpg', 'https://commons.wikimedia.org/wiki/File:A_Street_Scene_in_Seoul,_1904.jpg', 'Unknown photographer', 'Public domain', 'Street', 'curated', 'Large-format film', 'Field camera', '50 mm equivalent', '100', '1/125 s', 'f/8', 'Daylight', null, '{}'::jsonb, '{"Contrast":"+12","Grain":"Medium","Preset":"Archive Mono"}'::jsonb),
('00000000-0000-4000-8000-000000000006', 'street-night', 'Street scene at night', 'Let a bright sign or window become the anchor in a low-light frame.', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/%28Street_Scene_at_Night%29%2C_by_Otto_H._Bacher.jpg', 'https://commons.wikimedia.org/wiki/File:(Street_Scene_at_Night),_by_Otto_H._Bacher.jpg', 'Otto Henry Bacher', 'Public domain', 'Street', 'curated', '35 mm film', '50 mm prime', '50 mm', '800', '1/125 s', 'f/2', 'Auto', '+0.3 EV', '{}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000007', 'full-body-lincoln', 'Full length, standing', 'Keep the camera level and leave clear space around the hands and feet.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Abraham_Lincoln%2C_full-length_portrait%2C_standing_LCCN2013648762.jpg/960px-Abraham_Lincoln%2C_full-length_portrait%2C_standing_LCCN2013648762.jpg', 'https://commons.wikimedia.org/wiki/File:Abraham_Lincoln,_full-length_portrait,_standing_LCCN2013648762.jpg', 'Alexander Gardner, Library of Congress', 'Public domain', 'Full Body', 'curated', 'Large-format film', 'Portrait camera', '80 mm equivalent', '100', '1/60 s', 'f/8', 'Daylight', null, '{"Body position":"Stand at a relaxed three-quarter angle","Hands":"Let one hand hold a prop","Legs":"Set one foot slightly forward","Head":"Turn gently toward the light"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000008', 'full-body-garden', 'Standing in open shade', 'Use a simple background and even light to keep the full silhouette readable.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Adele_Romany_-_Portrait_of_a_gentleman%2C_full-length%2C_standing_in_a_landscape.jpg/960px-Adele_Romany_-_Portrait_of_a_gentleman%2C_full-length%2C_standing_in_a_landscape.jpg', 'https://commons.wikimedia.org/wiki/File:Adele_Romany_-_Portrait_of_a_gentleman,_full-length,_standing_in_a_landscape.jpg', 'Adèle Romany', 'Public domain', 'Full Body', 'curated', 'Large-format film', 'Field camera', '70 mm equivalent', '100', '1/125 s', 'f/5.6', 'Daylight', null, '{"Body position":"Stand with weight on the back leg","Hands":"Keep hands relaxed","Legs":"Leave a small gap between the feet"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000009', 'full-body-friends', 'Together in the frame', 'A group portrait feels relaxed when each person has their own silhouette.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/George_Foster_and_two_other_children%2C_full_length_portrait_-_DPLA_-_debe2507d3299e4e075d3e45fe0c59e0_%28page_1%29.jpg/960px-George_Foster_and_two_other_children%2C_full_length_portrait_-_DPLA_-_debe2507d3299e4e075d3e45fe0c59e0_%28page_1%29.jpg', 'https://commons.wikimedia.org/wiki/File:George_Foster_and_two_other_children,_full_length_portrait_-_DPLA_-_debe2507d3299e4e075d3e45fe0c59e0_(page_1).jpg', 'Boynton', 'Public domain', 'Full Body', 'curated', 'Large-format film', 'Field camera', '50 mm equivalent', '100', '1/60 s', 'f/8', 'Daylight', null, '{"Body position":"Stand close without overlapping shoulders","Gaze":"Look toward the same point"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000010', 'lifestyle-cafe-window', 'A table by the window', 'Let the environment tell part of the story, then keep the subject unhurried.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/A_photograph_of_Cafe_Local%2C_a_cafe_serving_Chatham_Railway_Station.jpg/960px-A_photograph_of_Cafe_Local%2C_a_cafe_serving_Chatham_Railway_Station.jpg', 'https://commons.wikimedia.org/wiki/File:A_photograph_of_Cafe_Local,_a_cafe_serving_Chatham_Railway_Station.jpg', 'Sunolafjagtenben-hur', 'CC0', 'Lifestyle', 'curated', 'Smartphone', 'Main camera', '24 mm equivalent', '200', '1/250 s', 'f/1.8', 'Auto', null, '{"Body position":"Lean lightly against the table","Hands":"Hold a cup in both hands","Gaze":"Look toward the window"}'::jsonb, '{"Highlights":"-15","Shadows":"+12","Temperature":"+4","Preset":"Warm Everyday"}'::jsonb),
('00000000-0000-4000-8000-000000000011', 'lifestyle-cafe-karbala', 'Coffee house, Karbala', 'Frame a quiet scene through a doorway to add depth and context.', 'https://upload.wikimedia.org/wikipedia/commons/e/e5/Cafe_in_Karbala_-_1909.jpg', 'https://commons.wikimedia.org/wiki/File:Cafe_in_Karbala_-_1909.jpg', 'Iraq Archive, unknown photographer', 'Public domain', 'Lifestyle', 'curated', 'Large-format film', 'Field camera', '35 mm equivalent', '100', '1/60 s', 'f/8', 'Daylight', null, '{}'::jsonb, '{"Contrast":"+7","Saturation":"-10","Grain":"Fine","Preset":"Dusty Archive"}'::jsonb),
('00000000-0000-4000-8000-000000000012', 'lifestyle-brussels', 'Inside the café', 'Use the lines of a counter or shelf to lead into a relaxed scene.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Delirium_Cafe%2C_Brussels.jpg/960px-Delirium_Cafe%2C_Brussels.jpg', 'https://commons.wikimedia.org/wiki/File:Delirium_Cafe,_Brussels.jpg', 'Nicolas Vigier', 'CC0', 'Lifestyle', 'curated', 'Mirrorless camera', '28 mm prime', '28 mm', '640', '1/100 s', 'f/2.8', 'Auto', null, '{}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000013', 'couple-garden', 'Close, not posed', 'Give a couple a small shared action so their attention stays with each other.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Portrait_of_unknown_young_couple%2C_ca._1894_-_DPLA_-_c301c944a2e4f06076562ef5fa32a486.jpg/960px-Portrait_of_unknown_young_couple%2C_ca._1894_-_DPLA_-_c301c944a2e4f06076562ef5fa32a486.jpg', 'https://commons.wikimedia.org/wiki/File:Portrait_of_unknown_young_couple,_ca._1894_-_DPLA_-_c301c944a2e4f06076562ef5fa32a486.jpg', 'Eggan Brothers; James P. Eggan', 'Public domain', 'Couple', 'curated', 'Large-format film', 'Portrait camera', '80 mm equivalent', '100', '1/60 s', 'f/5.6', 'Daylight', null, '{"Body position":"Stand shoulder to shoulder","Hands":"Rest hands naturally together","Gaze":"Look at each other, not the camera"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000014', 'couple-portrait-1897', 'A shared portrait', 'Keep both faces at a similar distance from the lens for even focus.', 'https://upload.wikimedia.org/wikipedia/commons/6/66/Oleksandra_Durnovo_and_Pavlo_Skoropadsky_%28Portrait_photography%2C_october_1897%29.jpg', 'https://commons.wikimedia.org/wiki/File:Oleksandra_Durnovo_and_Pavlo_Skoropadsky_(Portrait_photography,_october_1897).jpg', 'Unknown photographer', 'Public domain', 'Couple', 'curated', 'Large-format film', 'Portrait camera', '85 mm equivalent', '100', '1/60 s', 'f/5.6', 'Daylight', null, '{"Body position":"Sit close with shoulders turned inward","Gaze":"Look toward the same point"}'::jsonb, '{"Temperature":"+6","Contrast":"+8","Grain":"Fine","Preset":"Warm Archive"}'::jsonb),
('00000000-0000-4000-8000-000000000015', 'couple-elderly', 'An easy conversation', 'Capture the exchange between people rather than asking for a fixed smile.', 'https://upload.wikimedia.org/wikipedia/commons/4/42/Unidentified_elderly_couple_%283968119087%29.jpg', 'https://commons.wikimedia.org/wiki/File:Unidentified_elderly_couple_(3968119087).jpg', 'National Library of Wales', 'Public domain', 'Couple', 'curated', 'Medium-format film', 'Portrait camera', '80 mm', '100', '1/125 s', 'f/4', 'Daylight', null, '{"Body position":"Sit at the same angle","Hands":"Hold hands loosely","Gaze":"Look toward each other"}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000016', 'car-moscow-mg', 'Chrome and curve', 'Shoot from a low three-quarter angle to bring out the car body lines.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Moscow_car_meet_2025-07-12_MG_03.jpg/960px-Moscow_car_meet_2025-07-12_MG_03.jpg', 'https://commons.wikimedia.org/wiki/File:Moscow_car_meet_2025-07-12_MG_03.jpg', 'Retired electrician', 'CC0', 'Car', 'curated', 'Mirrorless camera', '24–70 mm zoom', '35 mm', '100', '1/250 s', 'f/5.6', 'Daylight', '-0.3 EV', '{}'::jsonb, '{"Highlights":"-20","Contrast":"+10","Saturation":"-3","Preset":"Chrome Detail"}'::jsonb),
('00000000-0000-4000-8000-000000000017', 'car-soviet-row', 'A row of classics', 'Use repetition and a longer focal length to compress a line of cars.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Moscow_car_meet_2025-07-12_Soviet_row_06.jpg/960px-Moscow_car_meet_2025-07-12_Soviet_row_06.jpg', 'https://commons.wikimedia.org/wiki/File:Moscow_car_meet_2025-07-12_Soviet_row_06.jpg', 'Retired electrician', 'CC0', 'Car', 'curated', 'Mirrorless camera', '70–200 mm zoom', '85 mm', '200', '1/320 s', 'f/4', 'Auto', null, '{}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000018', 'car-paris-arc', 'Passing through Paris', 'Wait for a clean gap and use the architecture to frame the vehicle.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Auto_op_de_Place_de_l%27%C3%89toile%2C_in_de_koplamp_is_de_weerspiegeling_van_de_Arc_de_T%2C_Bestanddeelnr_191-0354.jpg/960px-Auto_op_de_Place_de_l%27%C3%89toile%2C_in_de_koplamp_is_de_weerspiegeling_van_de_Arc_de_T%2C_Bestanddeelnr_191-0354.jpg', 'https://commons.wikimedia.org/wiki/File:Auto_op_de_Place_de_l%27Étoile,_in_de_koplamp_is_de_weerspiegeling_van_de_Arc_de_T,_Bestanddeelnr_191-0354.jpg', 'Willem van de Poll', 'CC0', 'Car', 'curated', '35 mm film', '50 mm prime', '50 mm', '200', '1/500 s', 'f/5.6', 'Daylight', null, '{}'::jsonb, '{}'::jsonb),
('00000000-0000-4000-8000-000000000019', 'product-tools', 'Tools on the counter', 'Arrange a small set of objects with enough negative space to read each shape.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Canon_Photography_Hairstyling_tool_barbershop_from_Iran_Mashhad_city_Mostafa_Meraji_09.jpg/960px-Canon_Photography_Hairstyling_tool_barbershop_from_Iran_Mashhad_city_Mostafa_Meraji_09.jpg', 'https://commons.wikimedia.org/wiki/File:Canon_Photography_Hairstyling_tool_barbershop_from_Iran_Mashhad_city_Mostafa_Meraji_09.jpg', 'Mostafameraji', 'CC0', 'Product', 'curated', 'Mirrorless camera', 'Macro lens', '60 mm', '100', '1/160 s', 'f/8', 'Daylight', null, '{}'::jsonb, '{"Contrast":"+4","Highlights":"-14","Saturation":"-5","Preset":"Clean Product"}'::jsonb),
('00000000-0000-4000-8000-000000000020', 'product-watch', 'A watch, simply framed', 'Keep a small object on a clean ground and leave room around its silhouette.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Cruciform_watch_Watch%2C_17th_century_%28CH_18457523%29.jpg/960px-Cruciform_watch_Watch%2C_17th_century_%28CH_18457523%29.jpg', 'https://commons.wikimedia.org/wiki/File:Cruciform_watch_Watch,_17th_century_(CH_18457523).jpg', 'Unknown artist', 'Public domain', 'Product', 'curated', 'Mirrorless camera', 'Macro lens', '90 mm', '100', '1/125 s', 'f/8', 'Custom', '-0.7 EV', '{}'::jsonb, '{"Highlights":"-25","Shadows":"+8","Grain":"Fine","Preset":"Still Life"}'::jsonb),
('00000000-0000-4000-8000-000000000021', 'product-mill', 'Made with care', 'Show the finished object in context while keeping the product easy to spot.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Finished_product_leaving_the_Durfee_Mill._LOC_nclc.03064.jpg/960px-Finished_product_leaving_the_Durfee_Mill._LOC_nclc.03064.jpg', 'https://commons.wikimedia.org/wiki/File:Finished_product_leaving_the_Durfee_Mill._LOC_nclc.03064.jpg', 'Lewis Wickes Hine, National Child Labor Committee Collection', 'Public domain', 'Product', 'curated', 'Large-format film', 'Field camera', '50 mm equivalent', '100', '1/60 s', 'f/5.6', 'Daylight', null, '{}'::jsonb, '{}'::jsonb)
